#define PI (acos(-1.))

//Shapes:
float sdSphere(vec3 p, float r)
{
    return (length(p)-r);
}

float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

//Operations:

float opUnion( float d1, float d2 )
{
    return min(d1,d2);
}
float opSubtraction( float d1, float d2 )
{
    return max(-d1,d2);
}
float opIntersection( float d1, float d2 )
{
    return max(d1,d2);
}
float opXor(float d1, float d2 )
{
    return max(min(d1,d2),-max(d1,d2));
}

float opSmoothUnion( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

float opSmoothSubtraction( float d1, float d2, float k )
{
    float h = clamp( 0.5 - 0.5*(d2+d1)/k, 0.0, 1.0 );
    return mix( d2, -d1, h ) + k*h*(1.0-h);
}

float opSmoothIntersection( float d1, float d2, float k )
{
    float h = clamp( 0.5 - 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) + k*h*(1.0-h);
}

mat2 Rot2D(float angle)
{
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c,-s,s,c);
}
//

float scene(vec3 p)
{
    vec3 SPos = vec3(sin(iTime)*4.,0,0);
    float displacement = sin(5.0 * p.x + iTime) * cos(5.0 * p.y+iTime) * sin(5.0 * p.z+iTime) * 0.25;
    float Sphere = sdSphere(p-SPos,1.)+displacement;
    float Box = sdBox(p,vec3(1.,1.,1.));

    return opSmoothUnion(Sphere,Box,3.);
}

vec3 calculate_normal(in vec3 p)//compute the gradient of the world's underlying sdf function, which is essentially the normal (kinda ...)
{
    const vec3 small_step = vec3(0.001, 0.0, 0.0);

    float gradient_x = scene(p + small_step.xyy) - scene(p - small_step.xyy);
    float gradient_y = scene(p + small_step.yxy) - scene(p - small_step.yxy);
    float gradient_z = scene(p + small_step.yyx) - scene(p - small_step.yyx);

    vec3 normal = vec3(gradient_x, gradient_y, gradient_z);

    return normalize(normal);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //Scene parameters:
    vec3 backgroundColor = vec3(1,1,1);


    // Normalized pixel coordinates (recentered from -1 to 1)
    vec2 uv = fragCoord/iResolution.xy;


    //Camera parameters:
    vec3 camPos = vec3(0,0,-5);
    vec3 camTarget = vec3(0,0,0);
    float aspectRatio = iResolution.x/iResolution.y;
    float fov = 70.;
    float focalLength = 1.;

    //Camera setup:

    vec2 m = iMouse.xy / iResolution.xy;

    float ax = iMouse.x < 2. ? -PI * .7 + iTime * .2 : -m.x * PI;
    float ay = iMouse.y < 2. ? 0.12 * PI : -m.y * PI + PI * 0.5;

    camPos.yz *= Rot2D(ay);
    camPos.xz *= Rot2D(ax);

    vec3 wUp = vec3(0,1,0);
    vec3 camLookAt = normalize(camTarget-camPos);
    vec3 camRight = normalize(cross(wUp, camLookAt));
    vec3 camUp = normalize(cross(camLookAt, camRight));

    float viewportHalfHeight = focalLength * tan(radians(fov*0.5))*2.;
    float viewportHalfWidth = viewportHalfHeight * aspectRatio;

    vec3 viewportBottomLeft = camPos + camLookAt * focalLength - camRight*(viewportHalfWidth/2.) - camUp * (viewportHalfHeight/2.);


    //Rays setup ad marching
    vec3 ro = camPos;
    vec3 rd = normalize((viewportBottomLeft + camRight * uv.x * viewportHalfWidth + camUp * uv.y * viewportHalfHeight) - camPos);


    float t = 0.;
    vec3 col = vec3(uv,0.);

    for(int i = 0; i<80 ; i++)
    {
        vec3 p = ro + rd*t;
        float d = scene(p);

        t += d;

        if(d<0.01)//hit (simple lambert for demonstration)
        {
            vec3 normal = calculate_normal(p);
            vec3 light_position = camLookAt;
            vec3 direction_to_light = normalize(p - light_position);

            float diffuse_intensity = max(0.0, dot(normal, direction_to_light));

            col =  vec3(.5, 0.4, .8) * diffuse_intensity;
        }

        if(t>100.)//miss
        {
            col = backgroundColor;
        }
    }


    // Output to screen
    fragColor = vec4(col,1.0);
}
